export const title = "How to Keep a Storage Cart From Blocking Drawers and Cabinet Doors";
export const metaTitle = "How to Keep a Storage Cart From Blocking";
export const metaDescription = "Plan the actions around parked storage. Practical measurements, original diagrams and fit checks for room movement in small workspaces.";
export const author = "Jamie Cole, Lead Product Researcher";
